var regex = /\{\s*"url"\s*:\s*"[^"]+"\s*,\s*"mobile"\s*:\s*"[^"]+"\s*,\s*"isk"\s*:\s*"[^"]+"\s*\}/;
var match = result.match(regex)[0];
var jsonObj = JSON.parse(match);
var params = "url=" + encodeURIComponent(jsonObj.url) + 
             "&mobile=" + encodeURIComponent(jsonObj.mobile) + 
             "&isk=" + encodeURIComponent(jsonObj.isk);
java.log(params);
let response = java.post("https://www.8xsk.info/conapi.php",params,{
    "accept": "application/json, text/javascript, */*; q=0.01",
    "accept-language": "zh-CN,zh;q=0.9,en;q=0.8,en-GB;q=0.7,en-US;q=0.6",
    "cache-control": "no-cache",
    "content-type": "application/x-www-form-urlencoded; charset=UTF-8",
    "origin": "https://www.8xsk.info",
    "pragma": "no-cache",
    "priority": "u=1, i",
    "sec-ch-ua": "\"Microsoft Edge\";v=\"143\", \"Chromium\";v=\"143\", \"Not A(Brand\";v=\"24\"",
    "sec-ch-ua-mobile": "?0",
    "sec-ch-ua-platform": "\"Windows\"",
    "sec-fetch-dest": "empty",
    "sec-fetch-mode": "cors",
    "sec-fetch-site": "same-origin",
    "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36 Edg/143.0.0.0",
    "x-requested-with": "XMLHttpRequest"
}
);
JSON.parse(response.body())["content"];

